CREATE TABLE IF NOT EXISTS campuses(id text PRIMARY KEY, name text NOT NULL, accent text NOT NULL, location text NOT NULL);
CREATE TABLE IF NOT EXISTS users(id text PRIMARY KEY, email text UNIQUE NOT NULL, name text NOT NULL);
CREATE TABLE IF NOT EXISTS roles(user_id text REFERENCES users(id), campus_id text REFERENCES campuses(id), role text CHECK(role IN ('curator','host','admin')), UNIQUE(user_id,campus_id,role));
CREATE TABLE IF NOT EXISTS sessions(token_hash text PRIMARY KEY, user_id text REFERENCES users(id), expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS otp_challenges(id text PRIMARY KEY, email text NOT NULL, code_hash text NOT NULL, attempts int NOT NULL DEFAULT 0, expires_at timestamptz NOT NULL, used boolean NOT NULL DEFAULT false);
CREATE INDEX IF NOT EXISTS otp_email_idx ON otp_challenges(email,expires_at);
CREATE TABLE IF NOT EXISTS drops(id text PRIMARY KEY, campus_id text NOT NULL REFERENCES campuses(id), title text NOT NULL, description text NOT NULL, kind text NOT NULL, price int NOT NULL CHECK(price>0), moq int NOT NULL CHECK(moq>0), state text NOT NULL DEFAULT 'PLEDGING', closes_at timestamptz NOT NULL, payment_ends_at timestamptz, snapshot jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS drops_campus_idx ON drops(campus_id);
CREATE TABLE IF NOT EXISTS variants(id text PRIMARY KEY, drop_id text NOT NULL REFERENCES drops(id), color text NOT NULL, size text NOT NULL, color_moq int NOT NULL DEFAULT 1 CHECK(color_moq>0), UNIQUE(drop_id,color,size));
CREATE TABLE IF NOT EXISTS pledges(id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), drop_id text NOT NULL REFERENCES drops(id), variant_id text NOT NULL REFERENCES variants(id), quantity int NOT NULL CHECK(quantity BETWEEN 1 AND 10), status text NOT NULL DEFAULT 'ACTIVE', request_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,request_key));
CREATE INDEX IF NOT EXISTS pledge_drop_idx ON pledges(drop_id,user_id);
CREATE TABLE IF NOT EXISTS orders(id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), campus_id text NOT NULL REFERENCES campuses(id), drop_id text NOT NULL REFERENCES drops(id), pledge_id text UNIQUE REFERENCES pledges(id), variant_id text NOT NULL REFERENCES variants(id), quantity int NOT NULL CHECK(quantity>0), total int NOT NULL CHECK(total>0), paid int NOT NULL DEFAULT 0 CHECK(paid>=0 AND paid<=total), fulfillment text NOT NULL DEFAULT 'AWAITING_PAYMENT', allocated int NOT NULL DEFAULT 0 CHECK(allocated>=0 AND allocated<=quantity), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS order_campus_idx ON orders(campus_id,user_id);
CREATE TABLE IF NOT EXISTS obligations(id text PRIMARY KEY, order_id text NOT NULL REFERENCES orders(id), amount int NOT NULL CHECK(amount>0), provider_order_id text UNIQUE, captured boolean NOT NULL DEFAULT false, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS payment_events(id text PRIMARY KEY, provider_payment_id text UNIQUE NOT NULL, obligation_id text NOT NULL UNIQUE REFERENCES obligations(id), amount int NOT NULL CHECK(amount>0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS stock(variant_id text PRIMARY KEY REFERENCES variants(id), campus_id text NOT NULL REFERENCES campuses(id), on_hand int NOT NULL DEFAULT 0 CHECK(on_hand>=0), allocated int NOT NULL DEFAULT 0 CHECK(allocated>=0 AND allocated<=on_hand));
CREATE TABLE IF NOT EXISTS movements(id text PRIMARY KEY, campus_id text NOT NULL REFERENCES campuses(id), variant_id text NOT NULL REFERENCES variants(id), kind text NOT NULL, quantity int NOT NULL, reference text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(kind,reference,variant_id));
CREATE TABLE IF NOT EXISTS receipts(id text PRIMARY KEY, drop_id text NOT NULL REFERENCES drops(id), actor text NOT NULL REFERENCES users(id), payload_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS receipt_lines(receipt_id text REFERENCES receipts(id), variant_id text REFERENCES variants(id), expected int NOT NULL, healthy int NOT NULL, damaged int NOT NULL, PRIMARY KEY(receipt_id,variant_id));
CREATE TABLE IF NOT EXISTS pickup_passes(order_id text PRIMARY KEY REFERENCES orders(id), token_hash text UNIQUE NOT NULL, expires_at timestamptz NOT NULL, used_at timestamptz);
CREATE TABLE IF NOT EXISTS pickup_events(order_id text PRIMARY KEY REFERENCES orders(id), host_id text NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit(id text PRIMARY KEY, campus_id text NOT NULL REFERENCES campuses(id), actor text NOT NULL REFERENCES users(id), action text NOT NULL, entity text NOT NULL, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS outbox(id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), message text NOT NULL, delivered_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
